// ─────────────────────────────────────────────
// ⚙️  CONFIGURE AQUI
// ─────────────────────────────────────────────
const BOT_URL = 'http://localhost:3001'; // onde o bot escuta o /notify (HTTP_PORT do .env do bot)
// ─────────────────────────────────────────────

const raw  = $input.first().json;
const p    = raw.body || raw;
const tipo = String(p.notification_type || '');

// Só estes tipos viram mensagem; o resto (pendente, aprovado, issues...) é ignorado
const TIPOS = {
  MEDIA_AVAILABLE:   { titulo: '✅ Chegou', cor: 0x57f287 },
  MEDIA_FAILED:      { titulo: '❌ Falhou o download de', cor: 0xed4245 },
  TEST_NOTIFICATION: { titulo: '🧪 Teste do Jellyseerr: a integração está funcionando', cor: 0x5865f2 },
};
const t = TIPOS[tipo];
if (!t) return [];

// Variável que a versão do Jellyseerr não conhece chega literal ("{{...}}"): vira vazio
const valor = (v) => (typeof v === 'string' && !v.includes('{{') ? v.trim() : '');

// ID do Discord de quem pediu: "discordId" até o Jellyseerr v3.2, "discordIds" do v3.3 em diante
// (pode vir "id1,id2"). Os dois são aceitos.
const req  = p.request || {};
const ids  = [valor(req.requestedBy_settings_discordIds), valor(req.requestedBy_settings_discordId)]
  .join(',')
  .split(/[\s,]+/)
  .filter((id) => /^\d{17,20}$/.test(id));
const mencoes = [...new Set(ids)];

const assunto = valor(p.subject) || 'Sem título';
const embed = {
  title: (tipo === 'TEST_NOTIFICATION' ? t.titulo : `${t.titulo}: ${assunto}`).slice(0, 256),
  color: t.cor,
};
const sinopse = valor(p.message);
if (sinopse) embed.description = sinopse.slice(0, 500);
if (valor(p.image).startsWith('https://')) embed.thumbnail = { url: valor(p.image) };

const fields = [];
for (const e of Array.isArray(p.extra) ? p.extra : []) {
  const nome = valor(e?.name), v = valor(e?.value);
  if (nome && v) fields.push({ name: nome === 'Requested Seasons' ? 'Temporadas' : nome, value: v.slice(0, 1024), inline: true });
}
const quem = valor(req.requestedBy_username);
if (quem) fields.push({ name: 'Pedido por', value: quem.slice(0, 1024), inline: true });
if (fields.length) embed.fields = fields;

// Só o aviso de "chegou" marca quem pediu
const marcar  = tipo === 'MEDIA_AVAILABLE' ? mencoes : [];
const payload = { embeds: [embed], channel: 'media', mentionUsers: marcar };
if (marcar.length) payload.content = `${marcar.map((id) => `<@${id}>`).join(' ')} seu pedido chegou! 🍿`;

return [{ json: { botUrl: BOT_URL.replace(/\/+$/, ''), payload } }];
